const _ = require('lodash');
const keys = require('../lib/keys');
const logger = require('../lib/logger');
const constant = require('../lib/constant');

/**
 * key:
 * keys
 * del key [key ...]
 * exists key
 * expire key seconds(TODO)
 * type key
 * flushall
 */
module.exports = (common) => {
  const operations = {
    * keys(configServant) {
      const keysInMemory = yield common.getAllMainKey();
      logger.dcache.info('keysInMemory', keysInMemory.length, keysInMemory);
      const keysInDB = yield keys.getKeysFromDb(common.module, configServant);
      logger.dcache.info('keysInDB', keysInDB.length, keysInDB);
      return _.union(keysInMemory, keysInDB);
    },

    * del(...keys) {
      keys = common.getFieldToArray(keys);
      /* istanbul ignore if */
      if (keys === null) {
        return 0;
      }
      if (keys.length > 1) {
        // TODO v2
        // let obj = yield common.getBatch2Obj(keys.filter(v => v));
        // let count = 0;
        // for(let key in obj) {
        //     if(yield common.delString(key)) {
        //         count ++;
        //     }
        // }
        for (const key of keys) {
          yield common.delString(key);
        }
      } else {
        // TODO v2
        // if(yield operations.exists(key)) {
        //     return yield common.delString(key) ? 1 : 0;
        // }
        return yield common.delString(keys[0]);
      }
      // TODO v2
      // return count;
      return true;
    },

    * exists(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      const ret = yield common.getString(key, forceMaster);
      if (ret === undefined) {
        return undefined;
      }
      return !!ret;
    },

    // TODO in v2
    // * expire(key, seconds) {
    //
    // },

    * type(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return constant.TYPE.NONE;
      }
      let data = yield common.getString(key, forceMaster);
      if (data === undefined) {
        return undefined;
      }
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(data)) {
        return constant.TYPE.NONE;
      }
      data = JSON.parse(data);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(data._t)) {
        return constant.TYPE.NONE;
      }
      return data._t;
    },

    * flushall(configServant) {
      let keys = yield operations.keys(configServant);
      if (keys.length <= 10000) {
        // sync
        return yield operations.del(keys);
      }
      // async
      let chunkedKeys = _.chunk(keys, 1000);
      for (const k of chunkedKeys) {
        yield k.map(v => common.delString(v));
      }
      keys = yield operations.keys(configServant);
      chunkedKeys = _.chunk(keys, 100);
      for (const k of chunkedKeys) {
        yield k.map(v => common.delString(v));
      }
      keys = yield operations.keys(configServant);
      return yield operations.del(keys);

    },
  };
  return operations;
};
